window.HALAL_AYAT = [{"s":1,"v":"2-4","name":"الفاتحة","ar":"ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ۝٢ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ۝٣ مَٰلِكِ يَوۡمِ ٱلدِّينِ ۝٤","ru":"Хвала Аллаху, Господу миров Милостивому, Милосердному Властелину Дня воздаяния","en":"[All] praise is [due] to Allah, Lord of the worlds The Entirely Merciful, the Especially Merciful Sovereign of the Day of Recompense","tr":"Hamd, Alemlerin Rabbi Allah'a mahsustur O Rahman ve Rahim'dir Din Gününün sahibidir","fr":"Louange à Allah, Seigneur de l'univers Le Tout Miséricordieux, le Très Miséricordieux Maître du Jour de la rétribution","es":"Todas las alabanzas son para Dios, Señor de todo cuanto existe el Compasivo, el Misericordioso Soberano absoluto del Día del Juicio Final","de":"(Alles) Lob gehört Allah, dem Herrn der Welten, dem Allerbarmer, dem Barmherzigen, dem Herrscher am Tag des Gerichts.","nl":"Alle lof en dank komt (alléén) Allah toe, de Bezitter van (alle) wereldwezens. De meest Barmhartige, de meest Genadevolle. De enige Eigenaar (van het tijdstip) van de Dag der Opstanding.","pt":"Louvor a Allah, O Senhor dos mundos. O Misericordioso, O Misericordiador. O Soberano do Dia do Juízo.","sr":"Sva hvala pripada Allahu, Gospodaru svih svetova. Milostivom, Samilosnom. Vladaru Sudnjega dana."},
{"s":2,"v":"45","name":"البقرة","ar":"وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ ۝٤٥","ru":"Обратитесь за помощью к терпению и намазу. Воистину, намаз является тяжким бременем для всех, кроме смиренных","en":"And seek help through patience and prayer, and indeed, it is difficult except for the humbly submissive [to Allah]","tr":"Sabır ve namazla Allah'a sığınıp yardım isteyin; Rablerine kavuşacaklarını ve Ona döneceklerini umanlar ve huşu duyanlardan başkasına namaz elbette ağır gelir","fr":"Et cherchez secours dans l'endurance et la salât: certes, la Salât est une lourde obligation, sauf pour les humbles","es":"Busquen socorro en la paciencia y la oración. El cumplimiento de la oración es difícil, excepto para los que se someten humildemente [a Dios]","de":"Und sucht Hilfe in der Standhaftigkeit und im Gebet! Es ist freilich schwer, nur nicht für die Demütigen,","nl":"En vraag hulp middels (het vermogen om) geduld (op te brengen in en om) het gebed (door de lusten en verlangens van de ego te bedwingen). En voorzeker, dit (gebed) is bijzonder zwaar en moeilijk behalve voor de khaashi’ien (degene die vrees hebben voor Allah gebaseerd op kennis, vandaar dat ze hun gebeden op tijd verrichten waar ze ook zijn)","pt":"E implorai ajuda, com a paciência e a oração. E por certo, esta oração é bem penosa, exceto para os humildes,","sr":"Pomozite se strpljenjem i molitvom, a to je, zaista, teško, osim poniznima,"},
{"s":2,"v":"152","name":"البقرة","ar":"فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ ۝١٥٢","ru":"Поминайте Меня, и Я буду помнить о вас. Благодарите Меня и не будьте неблагодарны Мне","en":"So remember Me; I will remember you. And be grateful to Me and do not deny Me","tr":"Artık Beni anın, Ben de sizi anayım; Bana şükredin, nankörlük etmeyin","fr":"Souvenez-vous de Moi donc. Je vous récompenserai. Remerciez-Moi et ne soyez pas ingrats envers Moi","es":"Recuérdenme que Yo los recordaré; agradézcanme y no sean ingratos","de":"Gedenkt Meiner, so gedenke Ich eurer. Seid Mir dankbar und seid nicht undankbar gegen Mich.","nl":"Gedenk Mij (o.a. in jullie gebeden), (dan) zal Ik jullie gedenken, en wees Mij dankbaar (voor de gunsten door gehoorzaamheid) en wees Mij nooit ondankbaar (door zondigheid).","pt":"Então, lembrai-vos de Mim, Eu Me lembrarei de vós. E agradecei- Me e não Me renegueis.","sr":"Zato se setite Mene (pokornošću), i Ja ću vas da se sećam (opraštanjem)! I zahvaljujte Mi, i nemojte Mi nezahvalni biti!"},
{"s":2,"v":"153","name":"البقرة","ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ ۝١٥٣","ru":"О те, которые уверовали! Обратитесь за помощью к терпению и намазу. Воистину, Аллах - с терпеливыми","en":"O you who have believed, seek help through patience and prayer. Indeed, Allah is with the patient","tr":"Ey İnananlar! Sabır ve namazla yardım dileyin. Allah, muhakkak ki sabredenlerle beraberdir","fr":"O les croyants! Cherchez secours dans l'endurance et la Salât. Car Allah est avec ceux qui sont endurants","es":"¡Oh, creyentes! Busquen ayuda en la paciencia y la oración; que Dios está con los pacientes","de":"O die ihr glaubt, sucht Hilfe in der Standhaftigkeit und im Gebet! Allah ist mit den Standhaften.","nl":"O gij die gelooft! Zoek hulp in geduld en gebed. Waarlijk. Allah is met de geduldigen.","pt":"Ó vós que credes! Implorai ajuda com a paciência e a oração. Por certo, Allah é com os perseverantes.","sr":"O vi koji verujete, tražite sebi pomoć u strpljivosti i molitvi! Allah je, zaista, uz strpljive."},
{"s":2,"v":"186","name":"البقرة","ar":"وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ ۝١٨٦","ru":"Если Мои рабы спросят тебя обо Мне, то ведь Я близок и отвечаю на зов молящегося, когда он взывает ко Мне. Пусть же они отвечают Мне и веруют в Меня, - быть может, они последуют верным путем","en":"And when My servants ask you, [O Muhammad], concerning Me - indeed I am near. I respond to the invocation of the supplicant when he calls upon Me. So let them respond to Me [by obedience] and believe in Me that they may be [rightly] guided","tr":"Kullarım sana Beni sorarlarsa, bilsinler ki Ben, şüphesiz onlara yakınım. Benden isteyenin, dua ettiğinde duasını kabul ederim. Artık onlar da davetimi kabul edip Bana inansınlar ki doğru yolda yürüyenlerden olsunlar","fr":"Et quand Mes serviteurs t'interrogent sur Moi.. alors Je suis tout proche: Je réponds à l'appel de celui qui Me prie quand il Me prie. Qu'ils répondent à Mon appel, et qu'ils croient en Moi, afin qu'ils soient bien guidés","es":"Y si Mis siervos te preguntan por Mí [¡oh, Mujámmad!, diles] que estoy cerca de ellos. Respondo la súplica de quien Me invoca. [Entonces] que me obedezcan y crean en Mí, que así se encaminarán","de":"Und wenn dich Meine Diener nach Mir fragen, so bin Ich nahe; Ich erhöre den Ruf des Bittenden, wenn er Mich anruft. So sollen sie nun auf Mich hören und an Mich glauben, auf daß sie besonnen handeln mögen.","nl":"(O Mohammed, als jouw metgezellen) en dus Mijn dienaren jou over Mij ondervragen (aangaande de manier van aanroeping, antwoord hen dan) dat Ik (de Alhorende) zeker in de buurt ben (d.m.v. Mijn allesomvattende kennis). (Dus alleen) Ik verhoor de smeekbeden van de aanbidder wanneer hij Mij aanroept. Laat hen dus Mij gehoorzamen en in Mij geloven, zodat velen recht geleid zullen zijn.","pt":"E quando Meus servos te perguntarem por Mim, por certo, estou próximo, atendo a súplica do suplicante, quando Me suplica. Que eles Me atendam, então, e creiam em Mim, na esperança de serem assisados.","sr":"A kada te sluge Moje za Mene upitaju, Ja sam, sigurno, blizu: odazivam se molbi molitelja kada Me zamoli. Zato, neka se i oni Meni odazovu i neka veruju u Mene, kako bi ispravnim putem krenuli."},
{"s":2,"v":"201","name":"البقرة","ar":"وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ ۝٢٠١","ru":"Но среди них есть такие, которые говорят: «Господь наш! Одари нас добром в этом мире и добром в Последней жизни и защити нас от мучений в Огне»","en":"But among them is he who says, \"Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire","tr":"Rabbimiz! Bize dünyada iyiyi, ahirette de iyiyi ver, bizi ateşin azabından koru\" diyenler vardır","fr":"Et il est des gens qui disent: «Seigneur! Accorde nous belle part ici-bas, et belle part aussi dans l'au-delà; et protège-nous du châtiment du Feu!»","es":"Pero entre ellos hay quienes dicen: \"¡Señor nuestro! Danos bienestar en esta vida y en la otra, y presérvanos del tormento del Fuego","de":"Unter ihnen gibt es aber auch solche, die sagen: „Unser Herr, gib uns im Diesseits Gutes und im Jenseits Gutes, und bewahre uns vor der Strafe des (Höllen)feuers!","nl":"En van hen is hij die zegt: “Onze Heer, schenk ons de goede (gunsten) in dit leven en de goede (gunsten) in het hiernamaals, en bescherm ons tegen de kwellingen van het vuur.”","pt":"E, dentre eles, há quem diga: \"Senhor nosso! Concede-nos, na vida terrena, beneficio e na Derradeira Vida, benefício; e guarda-nos do castigo do Fogo.\"","sr":"A ima i onih koji govore: \"Gospodaru naš, daj nam dobro i na ovom svetu i na Budućem svetu i sačuvaj nas patnje u Paklu!\""},
{"s":3,"v":"8","name":"آل عمران","ar":"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ۝٨","ru":"Господь наш! Не уклоняй наши сердца в сторону после того, как Ты наставил нас на прямой путь, и даруй нам милость от Себя, ведь Ты - Дарующий","en":"[Who say], \"Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower","tr":"Rabbimiz! Bizi doğru yola erdirdikten sonra kalblerimizi eğriltme, katından bize rahmet bağışla; şüphesiz Sen sonsuz bağışta bulunansın","fr":"«Seigneur! Ne laisse pas dévier nos cœurs après que Tu nous aies guidés; et accorde-nous Ta miséricorde. C'est Toi, certes, le Grand Donateur","es":"¡Señor nuestro! No permitas que nuestros corazones se desvíen después de habernos guiado. Concédenos Tu misericordia, Tú eres el Dadivoso","de":"Unser Herr, lasse unsere Herzen nicht abschweifen, nachdem Du uns rechtgeleitet hast, und schenke uns Erbarmen von Dir aus. Du bist ja der unablässig Schenkende.","nl":"Zij zeggen: “Onze Heer! Doe onze harten niet van de waarheid afdwalen, nadat U ons (daar naartoe) heeft geleid en schenk ons van Uw zijde genade. Waarlijk, U bent de Schenker.”","pt":"Senhor nosso! Não nos desvies os corações do caminho reto, após nos haveres guiado; e dadiva-nos, de Tua parte, com misericórdia. Por certo, Tu, Tu és O Dadivoso.","sr":"\"Gospodaru naš, ne dopusti srcima našim da skrenu, kada si nam već na Pravi put ukazao, i daruj nam Svoju milost; Ti si, uistinu, Onaj Koji obilno daruje!"},
{"s":3,"v":"139","name":"آل عمران","ar":"وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ ۝١٣٩","ru":"Не слабейте и не печальтесь, в то время как вы будете на высоте, если вы действительно являетесь верующими","en":"So do not weaken and do not grieve, and you will be superior if you are [true] believers","tr":"Gevşemeyin, üzülmeyin, inanmışsanız, mutlaka siz en üstünsünüzdür","fr":"Ne vous laissez pas battre, ne vous affligez pas alors que vous êtes les supérieurs, si vous êtes de vrais croyants","es":"No se desanimen ni entristezcan, porque los que obtendrán el éxito finalmente serán los creyentes","de":"Und werdet nicht schwach noch seid traurig, wo ihr doch die Oberhand haben werdet, wenn ihr gläubig seid.","nl":"Verzwak niet en treur niet (over het voorval te Oehoed) want jullie zullen hen zeker overwinnen, indien jullie oprechte gelovigen zijn.","pt":"E não vos desanimeis nem vos entristeçais enquanto sois os superiores se sois crentes.","sr":"Ne klonite duhom, i ne žalostite se! Vi ćete da pobedite, ako vernici budete."},
{"s":3,"v":"190","name":"آل عمران","ar":"إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ ۝١٩٠","ru":"Воистину, в сотворении небес и земли, а также в смене ночи и дня заключены знамения для обладающих разумом","en":"Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding","tr":"Göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelmesinde akıl sahiblerine şüphesiz deliller vardır","fr":"En vérité, dans la création des cieux et de la terre, et dans l'alternance de la nuit et du jour, il y a certes des signes pour les doués d'intelligence","es":"En la creación de los cielos y de la Tierra, y en la sucesión de la noche y el día, hay signos para los dotados de intelecto","de":"In der Schöpfung der Himmel und der Erde und in dem Unterschied von Nacht und Tag liegen wahrlich Zeichen für diejenigen, die Verstand besitzen,","nl":"Waarlijk! In de schepping van de hemelen en de aarde en in de afwisseling van de nacht en de dag zijn er waarlijk tekenen voor mensen van begrip.","pt":"Por certo, na criação dos céus e da terra, e na alternância da noite e do dia, há sinais para os dotados de discernimento.","sr":"U stvaranju nebesa i Zemlje, i u izmeni noći i dana, zaista su znakovi za razumom obdarene,"},
{"s":3,"v":"200","name":"آل عمران","ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ۝٢٠٠","ru":"О те, которые уверовали! Будьте терпеливы, запасайтесь терпением, несите службу на заставах и бойтесь Аллаха, - быть может, вы преуспеете","en":"O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful","tr":"Ey İnananlar! Sabredin, düşmanlarınızdan daha sabırlı olun, cihada hazır bulunun, Allah'a karşı gelmekten sakının ki başarıya erişebilesiniz","fr":"O les croyants! Soyez endurants. Incitez-vous à l'endurance. Luttez constamment (contre l'ennemi) et craignez Allah, afin que vous réussissiez","es":"¡Oh, creyentes! Tengan paciencia, perseverancia, defiéndanse y tengan temor de Dios, que así tendrán éxito","de":"O die ihr glaubt, geduldet euch, haltet standhaft aus, seid kampfbereit und fürchtet Allah, auf daß es euch wohl ergehen möge!","nl":"O jullie die geloven! Heb geduld en wees standvastig. En dicht de kloven in jullie ‘territorium’). En vrees Allah opdat jullie zullen slagen.","pt":"Ó vós que credes! Pacientai e perseverai na paciência; e sede constantes na vigilância e temei a Allah, na esperança de serdes bem-aventurados.","sr":"O vi koji verujete, budite strpljivi i izdržljivi, ustrajno bdijte i bojte se Allaha, da biste uspeli!"},
{"s":4,"v":"28","name":"النساء","ar":"يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا ۝٢٨","ru":"Аллах желает вам облегчения, ведь человек создан слабым","en":"And Allah wants to lighten for you [your difficulties]; and mankind was created weak","tr":"İnsan zayıf yaratılmış olduğundan Allah sizden yükü hafifletmek ister","fr":"Allah veut vous alléger (les obligations,) car l'homme a été créé faible","es":"Dios facilita las cosas, ya que el ser humano fue creado con una naturaleza débil","de":"Allah will es euch leicht machen, denn der Mensch ist (ja) schwach erschaffen.","nl":"Allah wenst (de last) voor jullie te verlichten; en de mens is zwak geschapen.","pt":"Allah deseja aliviar-vos as difículdades. E foi criado frágil o ser humano.","sr":"Allah želi da vam olakša, a čovek je stvoren slab."},
{"s":6,"v":"162","name":"الأنعام","ar":"قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ۝١٦٢","ru":"Скажи: «Воистину, мой намаз и мое жертвоприношение (или поклонение), моя жизнь и моя смерть посвящены Аллаху, Господу миров","en":"Say, \"Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allah, Lord of the worlds","tr":"De ki: \"Namazım, ibadetlerim, hayatım ve ölümüm, alemlerin Rabbi Allah içindir","fr":"Dis: «En vérité, ma Salât, mes actes de dévotion, ma vie et ma mort appartiennent à Allah, Seigneur de l'Univers","es":"Diles: \"Mi oración, mi ofrenda, mi vida y mi muerte pertenecen a Dios, Señor del universo","de":"Sag: Gewiß, mein Gebet und mein (Schlacht)opfer, mein Leben und mein Sterben gehören Allah, dem Herrn der Weltenbewohner.","nl":"Zeg: “Waarlijk mijn gebed, mijn offer, mijn leven en mijn dood zijn voor Allah, de Heer van de wereldwezens.","pt":"Dize: \"Por certo, minha oração e meu culto e minha vida e minha morte são de Allah, O Senhor dos mundos.\"","sr":"Reci: „Molitva moja, i obredi moji, i život moj, i smrt moja zaista su radi Allaha, Gospodara svetova,"},
{"s":7,"v":"23","name":"الأعراف","ar":"قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ۝٢٣","ru":"Они сказали: «Господь наш! Мы поступили несправедливо по отношению к себе, и если Ты не простишь нас и не смилостивишься над нами, то мы непременно окажемся одними из потерпевших урон»","en":"They said, \"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers","tr":"Her ikisi, \"Rabbimiz! Kendimize yazık ettik; bizi bağışlamaz ve bize merhamet etmezsen biz kaybedenlerden oluruz\" dediler","fr":"Tous deux dirent: «O notre Seigneur, nous avons fait du tort à nous-mêmes. Et si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants»","es":"Ellos dijeron [arrepentidos]: \"¡Señor nuestro! Hemos sido injustos con nosotros mismos; si no nos perdonas y nos tienes misericordia, seremos de los perdidos","de":"Sie sagten: Unser Herr, wir haben uns selbst Unrecht zugefügt. Wenn Du uns nicht vergibst und Dich unser erbarmst, werden wir ganz gewiß zu den Verlorenen gehören.","nl":"Zij zeiden: “O Heer, wij hebben onszelf onrecht aangedaan (d.m.v. zonden). Als U ons niet vergeeft en ons Uw genade niet schenkt, dan zullen wij zeker tot de verliezers behoren.”","pt":"Disseram: \"Senhor nosso! Fomos injustos com nós mesmos e, se não nos perdoares e não tiveres misericórdia de nós estaremos, em verdade, dentre os perdedores.\"","sr":"„Gospodaru naš“, rekoše oni, „sami smo sebi nepravdu učinili, i ako nam Ti ne oprostiš i ne smiluješ nam se, sigurno ćemo da nastradamo.“"},
{"s":9,"v":"51","name":"التوبة","ar":"قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝٥١","ru":"Скажи: «Нас постигнет только то, что предписано нам Аллахом. Он - наш Покровитель. И пусть верующие уповают на одного Аллаха»","en":"Say, \"Never will we be struck except by what Allah has decreed for us; He is our protector.\" And upon Allah let the believers rely","tr":"De ki: \"Allah'ın bize yazdığından başkası başımıza gelmez. O bizim Mevlamızdır, inananlar Allah'a güvensin","fr":"Dis: «Rien ne nous atteindra, en dehors de ce qu'Allah a prescrit pour nous. Il est notre Protecteur. C'est en Allah que les croyants doivent mettre leur confiance»","es":"Diles [¡oh, Mujámmad!]: \"Solo nos sucede lo que Dios decretó para nosotros. Él es nuestro Protector, y a Dios se encomiendan los creyentes","de":"Sag: Uns wird nur das treffen, was Allah für uns bestimmt hat. Er ist unser Schutzherr. Auf Allah sollen sich die Gläubigen verlassen.","nl":"Zeg: “Niets zal ons gebeuren, behalve wat Allah voor ons bevolen heeft. Hij is onze helper.” En in Allah leggen de gelovigen hun vertrouwen.","pt":"Dize: \"Não nos alcançará senão o que Allah nos prescreveu. Ele é nosso Protetor.\" E que os crentes, então, confiem em Allah.","sr":"Reci: „Dogodiće nam se samo ono što nam Allah odredi, On je naš Gospodar, i neka se vernici samo u Allaha pouzdaju!“"},
{"s":13,"v":"28","name":"الرعد","ar":"ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ ۝٢٨","ru":"Они уверовали, и их сердца утешаются поминанием Аллаха. Разве не поминанием Аллаха утешаются сердца","en":"Those who have believed and whose hearts are assured by the remembrance of Allah. Unquestionably, by the remembrance of Allah hearts are assured","tr":"Onlar inanmışlar, kalbleri Allah'ı anmakla huzura kavuşmuştur. Dikkat edin, kalbler ancak Allah'ı anmakla huzura kavuşur","fr":"ceux qui ont cru, et dont les cœurs se tranquillisent à l'évocation d'Allah». Certes, c'est par l'évocation d'Allah que les cœurs se tranquillisent","es":"Los corazones de los creyentes se sosiegan con el recuerdo de Dios. ¿Acaso no es con el recuerdo de Dios que se sosiegan los corazones","de":"(Es sind) diejenigen, die glauben und deren Herzen im Gedenken Allahs Ruhe finden. Sicherlich, im Gedenken Allahs finden die Herzen Ruhe!","nl":"Degenen die geloven (hebben) harten (die) rust vinden in het gedenken van Allah. Inderdaad, tijdens het gedenken van Allah komen de harten tot rust!","pt":"\"Os que crêem e cujos corações se tranqüilizam com a lembrança de Allah.\" Ora, é com a lembrança de Allah que os corações se tranqüilizam.","sr":"One koji veruju i čija se srca, kad se Allah spomene, smiruju - a srca se, zaista, smiruju kad se Allah spomene."},
{"s":14,"v":"7","name":"ابراهيم","ar":"وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ ۝٧","ru":"Вот ваш Господь возвестил: «Если вы будете благодарны, то Я одарю вас еще большим. А если вы будете неблагодарны, то ведь мучения от Меня тяжки»","en":"And [remember] when your Lord proclaimed, 'If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe","tr":"Rabbiniz: \"Şükrederseniz and olsun ki, size karşılığını artıracağım; nankörlük ederseniz bilin ki azabım pek çetindir\" diye bildirmişti","fr":"Et lorsque votre Seigneur proclama: «Si vous êtes reconnaissants, très certainement J'augmenterai [Mes bienfaits] pour vous. Mais si vous êtes ingrats, Mon châtiment sera terrible»","es":"Y cuando su Señor anunció: \"Si Le agradecen, Él incrementará su sustento; y sepan que si lo rechazan, Su castigo será severo","de":"Und als euer Herr ankündigte: ,Wenn ihr dankbar seid, werde Ich euch ganz gewiß noch mehr (Gunst) erweisen. Wenn ihr jedoch undankbar seid, dann ist meine Strafe fürwahr streng.","nl":"En (gedenk) toen jullie Heer verklaarde: “Als jullie dank betuigen, dan geef Ik jullie meer maar als jullie ondankbaar zijn, waarlijk! Mijn bestraffing is zeker zwaar.”","pt":"E, de quando vosso Senhor noticiou: \"Em verdade, se agradeceis, acrescentar-vos-ei Minhas graças. Mas, em verdade, se estais ingratos, por certo, Meu castigo será veemente\"","sr":"I kad je vaš Gospodar objavio: „Ako budete zahvalni, Ja ću sigurno još više da vam dam; budete li nezahvalni, zaista će žestoka da bude Moja kazna.“"},
{"s":15,"v":"99","name":"الحجر","ar":"وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ ۝٩٩","ru":"Поклоняйся Господу твоему, пока убежденность (смерть) не явится к тебе","en":"And worship your Lord until there comes to you the certainty (death)","tr":"Rabbini hamd ile an, secde edenlerden ol ve ölünceye kadar Rabbine kulluk et","fr":"et adore ton Seigneur jusqu'à ce que te vienne la certitude (la mort)","es":"y adora a tu Señor hasta que te llegue la certeza","de":"und diene deinem Herrn, bis die Gewißheit zu dir kommt.","nl":"En aanbid jouw Heer totdat de zekerheid jouw neemt (de dood).","pt":"E adora teu Senhor, até chegar-te a certeza.","sr":"i Gospodara svoga obožavaj sve dok ti smrt ne dođe!"},
{"s":16,"v":"97","name":"النحل","ar":"مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ ۝٩٧","ru":"Верующих мужчин и женщин, которые поступали праведно, Мы непременно одарим прекрасной жизнью и вознаградим за лучшее из того, что они совершали","en":"Whoever does righteousness, whether male or female, while he is a believer - We will surely cause him to live a good life, and We will surely give them their reward [in the Hereafter] according to the best of what they used to do","tr":"Kadın, erkek, inanmış olarak kim iyi iş işlerse, ona hoş bir hayat yaşatacağız. Ecirlerini yaptıklarından daha güzeli ile ödeyeceğiz","fr":"Quiconque, mâle ou femelle, fait une bonne œuvre tout en étant croyant, Nous lui ferons vivre une bonne vie. Et Nous les récompenserons, certes, en fonction des meilleures de leurs actions","es":"Al creyente que obre rectamente, sea varón o mujer, le concederé una vida buena y le multiplicaré la recompensa de sus buenas obras","de":"Wer rechtschaffen handelt, sei es Mann oder Frau, und dabei gläubig ist, den werden Wir ganz gewiß ein gutes Leben leben lassen. Und Wir werden ihnen ganz gewiß mit ihrem Lohn das Beste von dem vergelten, was sie taten.","nl":"Al wie goede daden verricht – of het nu om mannen of vrouwen gaat – in de staat van een ware gelovige (door afstand te nemen van ongeloof, ongehoorzaamheid en zonden), schenken Wij een begerenswaardig leven (gevuld met ware geluk en voldoening en toegestane voorzieningen) en (in het hiernamaals) zullen Wij hen vast en zeker een beloning geven die in overeenstemming zal zijn met het beste van de verrichte daden.","pt":"A quem faz o bem, seja varão ou varoa, enquanto crente, certamente, fá-lo-emos viver vida benigna. E Nós recompensá-los-emos com prêmio melhor que aquilo que faziam.","sr":"Onom ko čini dobro, bio muškarac ili žena, a vernik je, Mi ćemo dati da proživi lep život i zaista ćemo ih nagraditi boljom nagradom nego što su zaslužili."},
{"s":16,"v":"128","name":"النحل","ar":"إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ ۝١٢٨","ru":"Воистину, Аллах - с теми, кто богобоязнен и кто творит добро","en":"Indeed, Allah is with those who fear Him and those who are doers of good","tr":"Allah şüphesiz sakınanlarla ve iyilik yapanlarla beraberdir","fr":"Certes, Allah est avec ceux qui [L'] ont craint avec piété et ceux qui sont bienfaisants","es":"Dios está con los piadosos y con los que hacen el bien","de":"Gewiß, Allah ist mit denjenigen, die gottesfürchtig sind und Gutes tun.","nl":"Waarlijk, Allah is met degenen die godsvrees voor Hem hebben, en de weldoeners onder hen (die in gehoorzaamheid hun intentie zuiveren).","pt":"Por certo, Allah é com os que são piedosos e com os que são benfeitores.","sr":"Allah je zaista na strani onih koji se Njega boje i greha klone i koji dobra dela čine."},
{"s":17,"v":"24","name":"الإسراء","ar":"وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ۝٢٤","ru":"Склони пред ними крыло смирения по милосердию своему и говори: «Господи! Помилуй их, ведь они растили меня ребенком»","en":"And lower to them the wing of humility out of mercy and say, \"My Lord, have mercy upon them as they brought me up [when I was] small","tr":"Onlara acıyarak alçak gönüllülük kanatlarını ger ve: \"Rabbim! Küçükken beni yetiştirdikleri gibi sen de onlara merhamet et!\" de","fr":"et par miséricorde, abaisse pour eux l'aile de l'humilité, et dis: «O mon Seigneur, fais-leur, à tous deux, miséricorde comme ils m'ont élevé tout petit»","es":"Trátenlos con humildad y compasión, y rueguen [por ellos diciendo]: \"¡Oh, Señor mío! Ten misericordia de ellos como ellos la tuvieron conmigo cuando me criaron siendo niño","de":"Und senke für sie aus Barmherzigkeit den Flügel der Demut und sag: Mein Herr, erbarme Dich ihrer, wie sie mich aufgezogen haben, als ich klein war.","nl":"En laat de vleugel van onderwerping en nederigheid door genade over hen neerdalen en zeg: “Onze Heer! Geef hen Uw genade, Zoals zij mij ook hebben mij opgevoed toen ik klein was.”","pt":"E baixa a ambos a asa da humildade, por misericórdia. E dize: \"Senhor meu! Tem misericórdia deles, como quando eles cuidaram de mim, enquanto pequenino\"","sr":"Budi prema njima pažljiv i ponizan i reci: “Gospodaru moj, smiluj im se, oni su mene, kad sam bio dete, negovali!”"},
{"s":18,"v":"10","name":"الكهف","ar":"إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ۝١٠","ru":"Вот юноши укрылись в пещере и сказали: «Господь наш! Даруй нам от Себя милость и устрой наше дело наилучшим образом»","en":"[Mention] when the youths retreated to the cave and said, \"Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance","tr":"Birkaç genç mağaraya sığınmış: \"Rabbimiz! Katından bize rahmet ver ve işimizde doğruyu göster, bizi başarılı kıl\" demişlerdi","fr":"Quand les jeunes gens se furent réfugiés dans la caverne, ils dirent: «O notre Seigneur, donne-nous de Ta part une miséricorde; et assure nous la droiture dans tout ce qui nous concerne»","es":"Recuerda cuando los jóvenes se refugiaron en la caverna y dijeron: \"¡Señor nuestro! Acógenos en Tu misericordia y concédenos que nuestra situación se solucione correctamente","de":"Als die Jünglinge in der Höhle Zuflucht suchten und sagten: „Unser Herr, gib uns Barmherzigkeit von Dir aus, und bereite uns in unserer Angelegenheit einen rechten (Aus)weg.","nl":"(Gedenk) toen de jonge mannen naar de Grot vluchten, zij zeiden: “Onze Heer! Schenk ons genade van U en vergemakkelijk onze zaak op een succesvolle manier!”","pt":"Quando os jovens se abrigaram na Caverna, e disseram: \"Senhor nosso! Concede-nos misericórdia de Tua parte e, para nós, dispõe retidão, em tudo o que nos concerna.\"","sr":"Kad se nekoliko momaka u pećini sklonilo pa kazalo: “Gospodaru naš, daj nam Svoju milost i pruži nam u ovom našem postupku prisebnost.”"},
{"s":20,"v":"25-28","name":"طه","ar":"قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ۝٢٥ وَيَسِّرۡ لِيٓ أَمۡرِي ۝٢٦ وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي ۝٢٧ يَفۡقَهُواْ قَوۡلِي ۝٢٨","ru":"Муса (Моисей) сказал: «Господи! Раскрой для меня мою грудь Облегчи мою миссию Развяжи узел на моем языке чтобы они могли понять мою речь","en":"[Moses] said, \"My Lord, expand for me my breast [with assurance] And ease for me my task And untie the knot from my tongue That they may understand my speech","tr":"Musa: \"Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin\" dedi Musa: \"Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin\" dedi Musa: \"Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin\" dedi Musa: \"Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin\" dedi","fr":"[Moïse] dit: «Seigneur, ouvre-moi ma poitrine et facilite ma mission et dénoue un nœud en ma langue afin qu'ils comprennent mes paroles","es":"Dijo [Moisés]: \"¡Oh, Señor mío! Abre mi corazón [y dame valor] facilita mi misión suelta el nudo que hay en mi lengua para que comprendan mis palabras","de":"Er sagte: „Mein Herr, weite mir meine Brust, und mache mir meine Angelegenheit leicht. Und löse den Knoten in meiner Zunge, so daß sie meine Worte verstehen.","nl":"(En Moesa u smeekte): “O mijn Heer! Verruim mijn hart voor mij (zodat ik deze zware boodschap kan dragen).” En maak mijn taak gemakkelijk voor mij; En maak de knoop van mijn tong los. Zodat zij mijn toespraak kunnen begrijpen.","pt":"Moisés disse: \"Senhor meu! Dilata-me o peito,\" \"E facilita-me a missão,\" \"E desata-me um nó da língua.\" \"Para que eles entendam meu dito,\"","sr":"„Moj Gospodaru“, reče Mojsije, „učini prostranim moja prsa, i olakšaj moj zadatak: odreši čvor sa mog jezika da bi razumeli moj govor"},
{"s":20,"v":"46","name":"طه","ar":"قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ ۝٤٦","ru":"Аллах сказал: «Не бойтесь, ибо Я - с вами. Я слышу и вижу","en":"[Allah] said, \"Fear not. Indeed, I am with you both; I hear and I see","tr":"Allah: Korkmayın, dedi; Ben sizinle beraberim; görür ve işitirim. Ona gidin şöyle söyleyin: \"Doğrusu biz senin Rabbinin elçileriyiz. İsrailoğullarını bizimle beraber gönder, onlara azabetme; Rabbinden sana bir mucize getirdik; selam, doğru yolda gidene olsun! Doğrusu bize, yalanlayıp sırt çevirene azap edileceği vahyolundu","fr":"Il dit: «Ne craignez rien. Je suis avec vous: J'entends et Je vois","es":"Dijo [Dios]: \"No tengan miedo, pues Yo estoy con ustedes escuchando y observando todo","de":"Er sagte: „Fürchtet euch nicht. Ich bin gewiß mit euch, Ich höre und Ich sehe (, was geschieht).","nl":"Hij zei: “Vrees niet, Waarlijk! Ik ben met jullie beiden, horend en ziend.","pt":"Ele disse: \"Não temais. Por certo, sou convosco: ouço e vejo.\"","sr":"“Ne bojte se!”, reče On, “Ja sam s vama, Ja sve čujem i vidim."},
{"s":21,"v":"87","name":"الأنبياء","ar":"وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّـٰلِمِينَ ۝٨٧","ru":"Помяни также человека в рыбе (Иунуса), который ушел в гневе и подумал, что Мы не справимся с ним. Он воззвал из мрака: «Нет божества, кроме Тебя! Пречист Ты! Воистину, я был одним из беззаконников!»","en":"And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, \"There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers","tr":"Zünnun (Balık Sahibi; Yunus) hakkında söylediğimizi de an. O, öfkelenerek giderken, kendisini sıkıntıya sokmayacağımızı sanmıştı; fakat sonunda karanlıklar içinde: \"Senden başka tanrı yoktur, Sen münezzehsin, doğrusu ben haksızlık edenlerdenim\" diye seslenmişti","fr":"Et Dû'n-Nûn (Jonas) quand il partit, irrité. Il pensa que Nous N'allions pas l'éprouver. Puis il fit, dans les ténèbres, l'appel que voici: «Pas de divinité à part Toi! Pureté à Toi! J'ai été vraiment du nombre des injustes»","es":"[El Profeta] Jonás, cuando se marchó enojado [con la gente de su pueblo que se negaron a creer en él], pensó que no lo iba a castigar [por no haber tenido paciencia, pero lo hice tragar por la ballena], e invocó desde la oscuridad [de su estómago]: \"No hay otra divinidad más que Tú. ¡Glorificado seas! En verdad he sido de los injustos","de":"Und (auch) dem Mann mit dem Fisch’, als er erzürnt wegging. Da meinte er, Wir würden ihm nicht (den Lebensunterhalt) bemessen. Dann rief er in den Finsternissen: „Es gibt keinen Gott außer Dir! Preis sei Dir! Gewiß, ich gehöre zu den Ungerechten.","nl":"En (gedenk) Dhan-Noen (Jonas), toen hij buiten zichzelf van woede was en dacht dat Wij het hem niet zouden zwaar maken! Maar hij riep door de duisternis (en in de maag van de walvis riep Yoenoes zijn Heer aan): “Niets of niemand heeft het recht op mijn aanbidding dan U. Perfect en verheerlijkt ben U. Want waarlijk, ik behoorde tot de zondaren.”","pt":"E Zan-Nūn quando se foi, irado, e pensou que não enviaríamos castigo contra ele; então, clamou nas trevas: \"Não existe deus, senão Tu! Glorificado sejas! Por certo, fui dos injustos.\"","sr":"Jonu kad srdit ode i pomisli da ga nećemo kazniti – pa posle u tminama zavapi: “Nema boga, osim Tebe, hvaljen neka si, a ja sam se zaista ogrešio prema sebi!”"},
{"s":21,"v":"107","name":"الأنبياء","ar":"وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ ۝١٠٧","ru":"Мы отправили тебя только в качестве милости к мирам","en":"And We have not sent you, [O Muhammad], except as a mercy to the worlds","tr":"Biz seni ancak alemlere rahmet olarak gönderdik","fr":"Et Nous ne t'avons envoyé qu'en miséricorde pour l'univers","es":"No te he enviado [¡oh, Mujámmad!] sino como misericordia para todos los seres","de":"Und Wir haben dich nur als Barmherzigkeit für die Weltenbewohner gesandt.","nl":"En Wij hebben jou (de Profeet Mohammed, vrede en zegeningen zij met hem) niet anders dan als genade voor de wereldwezens gestuurd.","pt":"E não te enviamos senão como misericórdia para os mundos.","sr":"a tebe smo poslali samo kao milost svetovima."},
{"s":25,"v":"63","name":"الفرقان","ar":"وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا ۝٦٣","ru":"А рабами Милостивого являются те, которые ступают по земле смиренно, а когда невежды обращаются к ним, они говорят: «Мир!»","en":"And the servants of the Most Merciful are those who walk upon the earth easily, and when the ignorant address them [harshly], they say [words of] peace","tr":"Rahman'ın kulları yeryüzünde mütevazı yürürler. Bilgisizler kendilerine takıldıkları zaman onlara güzel ve yumuşak söz söylerler","fr":"Les serviteurs du Tout Miséricordieux sont ceux qui marchent humblement sur terre, qui, lorsque les ignorants s'adressent à eux, disent: «Paix»","es":"Los siervos del Misericordioso son aquellos que caminan sobre la faz de Tierra con humildad, y cuando son increpados por los ignorantes les responden [con palabras de] paz","de":"Die Diener des Allerbarmers sind diejenigen, die maßvoll auf der Erde umhergehen und die, wenn die Toren sie ansprechen, sagen: „Frieden!","nl":"En de slaven van de Barmhartige zijn degenen die nederig en kalm over de aarde lopen, en als de onwetenden hen aanspreken antwoorden zij met \"Salaam\" (met milde woorden of vriendelijkheid).","pt":"E os servos dO Misericordioso são os que andam, mansamente, sobre a terra e, quando os ignorantes se dirigem a eles, dizem: \"Salam!\",\"Paz!\";","sr":"A sluge Milostivog su oni koji se po Zemlji u miru kreću, a kad im se bestidnici obrate, odgovaraju: “Mir vama!”"},
{"s":25,"v":"74","name":"الفرقان","ar":"وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا ۝٧٤","ru":"Они говорят: «Господь наш! Даруй нам отраду глаз в наших супругах и потомках и сделай нас образцом для богобоязненных»","en":"And those who say, \"Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous","tr":"Onlar: \"Rabbimiz! Bize eşlerimizden ve çocuklarımızdan gözümüzün aydınlığı olacak insanlar ihsan et ve bizi, Allah'a karşı gelmekten sakınanlara önder yap\" derler","fr":"et qui disent: «Seigneur, donne-nous, en nos épouses et nos descendants, la joie des yeux, et fais de nous un guide pour les pieux»","es":"Aquellos que piden: \"¡Oh, Señor nuestro! Agrácianos con cónyuges y descendientes que sean un motivo de alegría y tranquilidad para nosotros, y haz que seamos un ejemplo para los que tienen temor [de Dios]","de":"Und diejenigen, die sagen: „Unser Herr, schenke uns an unseren Gattinnen und unseren Nachkommenschaften Grund zur Freude, und mache uns für die Rechtschaffenen zu einem Vorbild.","nl":"En degenen die zeggen: “Onze Heer! Schenk ons van onze vrouwen en ons nageslacht een verkoeling voor onze ogen zijn en maak ons leiders van de godvrezenden.”","pt":"E os que dizem: \"Senhor nosso! Dadiva-nos, da parte de nossas mulheres e de nossa descendência, com alegre frescor nos olhos e faze-nos guia para os piedosos.\"","sr":"i oni koji govore: “Gospodaru naš, podari nam u ženama našim i deci našoj radost i učini da se čestiti na nas ugledaju!”"},
{"s":29,"v":"69","name":"العنكبوت","ar":"وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ ۝٦٩","ru":"А тех, которые сражаются ради Нас, Мы непременно поведем Нашими путями. Воистину, Аллах - с творящими добро","en":"And those who strive for Us - We will surely guide them to Our ways. And indeed, Allah is with the doers of good","tr":"Ama Bizim uğrumuzda cihat edenleri elbette yollarımıza eriştireceğiz. Allah şüphesiz, iyi davrananlarla beraberdir","fr":"Et quant à ceux qui luttent pour Notre cause, Nous les guiderons certes sur Nos sentiers. Allah est en vérité avec les bienfaisants","es":"A quienes se esfuercen por Mi causa los guiaré por Mis caminos. Dios está con los que hacen el bien","de":"Diejenigen aber, die sich um Unsertwillen abmühen, werden Wir ganz gewiß Unsere Wege leiten. Und Allah ist wahrlich mit den Gutes Tuenden.","nl":"En wat degene betreft die hard voor Ons streven, Wij zullen hen zeker naar Onze paden leiden. En waarlijk, Allah is met de weldoeners.","pt":"E aos que lutam por Nós, certamente, guiá-los-emos a Nossos caminhos. E, por certo, Allah é com os benfeitores.","sr":"One koji se budu trudili zbog Nas, Mi ćemo, sigurno, da uputimo putevima koji Nama vode, a Allah je, zaista, na strani onih koji dobra dela čine!"},
{"s":33,"v":"41-42","name":"الأحزاب","ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ۝٤١ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ۝٤٢","ru":"О те, которые уверовали! Поминайте Аллаха многократно и славьте Его утром и перед закатом","en":"O you who have believed, remember Allah with much remembrance And exalt Him morning and afternoon","tr":"Ey inananlar! Allah'ı çok anın O'nu sabah akşam tesbih edin","fr":"O vous qui croyez! Evoquez Allah d'une façon abondante et glorifiez-Le à la pointe et au déclin du jour","es":"¡Oh, creyentes! Tengan presente a Dios en todo momento y glorifíquenlo por la mañana y por la tarde","de":"O die ihr glaubt, gedenkt Allahs in häufigem Gedenken und preist Ihn morgens und abends.","nl":"O jullie die geloven! Gedenk Allah veelvuldig. (Dus) verheerlijk en loof Hem ’s morgens en ’s avonds.","pt":"Ó vós que credes! Invocai a Allah abundantemente. E glorificai-O, ao alvorecer e ao entardecer","sr":"O vernici, Allaha puno spominjite i ujutru i naveče Ga slavite i veličajte;"},
{"s":39,"v":"53","name":"الزمر","ar":"۞قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ۝٥٣","ru":"Скажи Моим рабам, которые излишествовали во вред самим себе: «Не отчаивайтесь в милости Аллаха. Воистину, Аллах прощает грехи полностью, ибо Он - Прощающий, Милосердный»","en":"Say, \"O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful","tr":"De ki: \"Ey kendilerine kötülük edip aşırı giden kullarım! Allah'ın rahmetinden umudunuzu kesmeyin. Doğrusu Allah günahların hepsini bağışlar. Çünkü O, bağışlayandır, merhametlidir","fr":"Dis: «O Mes serviteurs qui avez commis des excès à votre propre détriment, ne désespérez pas de la miséricorde d'Allah. Car Allah pardonne tous les péchés. Oui, c'est Lui le Pardonneur, le Très Miséricordieux","es":"Di: \"¡Oh, siervos míos que están sumidos en el pecado [perjudicándose a sí mismos]! No desesperen de la misericordia de Dios. Dios tiene poder para perdonar todos los pecados. Él es el Perdonador, el Misericordioso","de":"Sag: O Meine Diener, die ihr gegen euch selbst maßlos gewesen seid, verliert nicht die Hoffnung auf Allahs Barmherzigkeit. Gewiß, Allah vergibt die Sünden alle. Er ist ja der Allvergebende und Barmherzige.","nl":"Zeg: “O Mijn slaven die tegen zichzelf onrecht hebben gepleegd! Wanhoop niet aan de genade van Allah (aangaande Zijn vergiffenis en toelating tot het paradijs), waarlijk Allah vergeeft alle zonden. Waarlijk, Hij is de meest Vergevende, de meest Barmhartige.","pt":"Dize: \"Ó Meus servos, que vos excedestes em vosso próprio prejuízo, não vos desespereis da misericórdia de Allah. Por certo, Allah perdoa todos os delitos. Por certo, Ele é O Perdoador, O Misericordiador.\"","sr":"Reci: “O sluge Moje koje ste se prema sebi ogrešili, ne gubite nadu u Allahovu milost! Allah će, sigurno, sve grehe da oprosti. On, zaista, mnogo prašta i On je Milostivi.“"},
{"s":40,"v":"60","name":"غافر","ar":"وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ۝٦٠","ru":"Ваш Господь сказал: «Взывайте ко Мне, и Я отвечу вам. Воистину, те, которые превозносятся над поклонением Мне, войдут в Геенну униженными»","en":"And your Lord says, \"Call upon Me; I will respond to you.\" Indeed, those who disdain My worship will enter Hell [rendered] contemptible","tr":"Rabbiniz: \"Bana dua edin ki duanıza icabet edeyim. Bana kulluk etmeyi büyüklüklerine yediremeyenler alçalmış olarak cehenneme gireceklerdir\" buyurmuştur","fr":"Et votre Seigneur dit: «Appelez-Moi, Je vous répondrai. Ceux qui, par orgueil, se refusent à M'adorer entreront bientôt dans l'Enfer, humiliés»","es":"Su Señor dice: \"Invóquenme, que responderé [sus súplicas]\". Pero quienes por soberbia se nieguen a adorarme, ingresarán al Infierno humillados","de":"Euer Herr sagt: Ruft Mich an, so erhöre Ich euch. Gewiß, diejenigen, die sich aus Hochmut weigern, Mir zu dienen, werden in die Hölle gedemütigt eingehen.","nl":"En jullie Heer zei: “Roep Mij aan (smeek) en Ik zal jullie verhoren. Waarlijk! Degene die Mijn aanbidding minachten zullen zeker in vernedering de hel binnentreden!”","pt":"E vosso Senhor disse: \"Suplicai-Me, Eu vos atenderei. Por certo, os que se ensoberbecem diante de Minha adoração entrarão na Geena, humilhados.\"","sr":"Vaš Gospodar kaže: „Pomolite Mi se, i ja ću vam se odazvati! Zaista, oni koji iz oholosti neće da Me obožavaju - ući će, sigurno, poniženi u Pakao.“"},
{"s":49,"v":"10","name":"الحجرات","ar":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ۝١٠","ru":"Воистину, верующие - братья. Посему примиряйте братьев и бойтесь Аллаха, - быть может, вы будете помилованы","en":"The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy","tr":"Şüphesiz müminler birbiri ile kardeştirler; öyle ise dargın olan kardeşlerinizin arasını düzeltin; Allah'tan sakının ki size acısın","fr":"Les croyants ne sont que des frères. Etablissez la concorde entre vos frères, et craignez Allah, afin qu'on vous fasse miséricorde","es":"Los creyentes son hermanos entre sí; reconcilien a sus hermanos y tengan temor de Dios para que Él les tenga misericordia","de":"Die Gläubigen sind doch Brüder. So stiftet Frieden zwischen euren beiden Brüdern und fürchtet Allah, auf daß ihr Erbarmen finden möget.","nl":"De gelovigen zijn niet anders dan broeders (dus geen mensen van innovatie noch ongeloof, maar broeders). Verzoen je dus met jullie broeders, en vrees Allah, zodat jullie genade kunnen ontvangen.","pt":"Os crentes não são que irmãos. Então, reconciliai vossos dois irmãos que pelejarem. E temei a Allah, na esperança de obterdes misericórdia.","sr":"Vernici su samo braća, zato pomirite svoja dva brata i bojte se Allaha da bi vam se ukazala milost."},
{"s":50,"v":"16","name":"ق","ar":"وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ ۝١٦","ru":"Мы сотворили человека и знаем, что нашептывает ему душа. Мы ближе к нему, чем яремная вена","en":"And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein","tr":"And olsun ki insanı Biz yarattık; nefsinin kendisine fısıldadıklarını biliriz; Biz ona şah damarından daha yakınız","fr":"Nous avons effectivement créé l'homme et Nous savons ce que son âme lui suggère et Nous sommes plus près de lui que sa veine jugulaire","es":"Creé al ser humano y sé cuáles son sus debilidades. Estoy más cerca de él que su propia vena yugular","de":"Wir haben ja den Menschen erschaffen und wissen, was (alles ihm) seine Seele einflüstert, und Wir sind ihm doch näher als seine Halsschlagader,","nl":"En zeker, Wij hebben de mens geschapen en Wij weten wat hij in zichzelf zegt. En Wij zijn hem nader dan zijn eigen halsslagader.","pt":"E, com efeito, criamos o ser humano e sabemos o que a alma lhe sussurra. E Nós estamos mais Próximos dele que a veia jugular,","sr":"Mi smo stvorili čoveka i znamo što mu šapuće njegova duša, i Mi smo mu bliži od vratne žile kucavice."},
{"s":55,"v":"13","name":"الرحمن","ar":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ۝١٣","ru":"Какую же из милостей вашего Господа вы считаете ложью","en":"So which of the favors of your Lord would you deny","tr":"Ey insanlar ve cinler! Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız","fr":"Lequel donc des bienfaits de votre Seigneur nierez-vous","es":"¿Acaso pueden negar alguna de las gracias que les ha concedido su Señor","de":"Welche der Wohltaten eures Herrn wollt ihr beide denn leugnen?","nl":"Welke gunsten van jullie Heer proberen jullie beiden (mens en djinn) te ontkennen?","pt":"- Então, qual das mercês de vosso Senhor vós ambos desmentis?","sr":"pa, koju blagodat svoga Gospodara poričete?!"},
{"s":93,"v":"3-5","name":"الضحى","ar":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ۝٣ وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ ۝٤ وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ ۝٥","ru":"Не покинул тебя твой Господь и не возненавидел Воистину, будущее для тебя лучше, чем настоящее Господь твой непременно одарит тебя, и ты будешь удовлетворен","en":"Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you] And the Hereafter is better for you than the first [life] And your Lord is going to give you, and you will be satisfied","tr":"Rabbin seni ne bıraktı ve ne de sana darıldı Doğrusu ahiret senin için dünyadan daha hayırlıdır Rabbin şüphesiz sana verecek ve sen de hoşnut olacaksın","fr":"Ton Seigneur ne t'a ni abandonné, ni détesté La vie dernière t'est, certes, meilleure que la vie présente Ton Seigneur t'accordera certes [Ses faveurs], et alors tu seras satisfait","es":"que tu Señor no te ha abandonado ni aborrecido [oh, Mujámmad] La vida del más allá será mejor para ti que esta Tu Señor te agraciará y te complacerás","de":"Dein Herr hat sich weder von dir verabschiedet noch haßt Er (dich). Und das Jenseits ist wahrlich besser für dich als das Diesseits. Und dein Herr wird dir wahrlich geben, und dann wirst du zufrieden sein.","nl":"Jouw Heer heeft je niet verlaten en noch haat hij jou (dus wanhoop nooit en blijf standvastig). En zeker is het hiernamaals beter voor jou dan het eerste. En waarlijk, jouw Heer zal je (onvoorwaardelijk van Zijn gunsten) geven zodat je tevreden zult zijn.","pt":"Teu Senhor não te abandonou nem te detestou. E, em verdade, a Derradeira Vida te é melhor que a primeira. E, em verdade, teu Senhor dar-te-á graças, e disso te agradarás.","sr":"tvoj Gospodar nije te ni napustio ni omrznuo! Budući svet je, zaista, bolji za tebe od ovog sveta, a tvoj Gospodar će ti sigurno podariti, pa ćeš zadovoljan biti."},
{"s":94,"v":"5-6","name":"الشرح","ar":"فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا ۝٥ إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا ۝٦","ru":"Воистину, за каждой тягостью наступает облегчение За каждой тягостью наступает облегчение","en":"For indeed, with hardship [will be] ease Indeed, with hardship [will be] ease","tr":"Elbette güçlükle beraber şüphesiz bir kolaylık vardır Gerçekten, güçlükle beraber bir kolaylık vardır","fr":"A côté de la difficulté est, certes, une facilité A côté de la difficulté est, certes, une facilité","es":"Luego de toda dificultad viene la facilidad Realmente, luego de toda dificultad viene la facilidad","de":"Also gewiß, mit der Erschwernis ist Erleichterung, gewiß, mit der Erschwernis ist Erleichterung.","nl":"Dus waarlijk, na ongemak komen er weer betere tijden. Waarlijk, na ongemak komen er weer betere tijden.","pt":"Então, por certo, com a dificuldade, há facilidade! Por certo, com a dificuldade, há facilidade!","sr":"Pa, zaista, sa mukom je olakšanje, zaista, sa mukom je olakšanje!"},
{"s":94,"v":"7-8","name":"الشرح","ar":"فَإِذَا فَرَغۡتَ فَٱنصَبۡ ۝٧ وَإِلَىٰ رَبِّكَ فَٱرۡغَب ۝٨","ru":"Посему, как только освободишься, будь деятелен (как только освободишься от мирских дел, усердно поклоняйся Аллаху, или как только завершишь намаз, усердно взывай к Аллаху с молитвами) и устремись к своему Господу","en":"So when you have finished [your duties], then stand up [for worship] And to your Lord direct [your] longing","tr":"Öyleyse, bir işi bitirince diğerine giriş Ve ümit edeceğini yalnız Rabbinden iste","fr":"Quand tu te libères, donc, lève-toi et à ton Seigneur aspire","es":"Cuando cumplas con tus obligaciones dedícate a la adoración y a tu Señor anhela con devoción","de":"Wenn du nun fertig bist, dann strenge dich an und nach deinem Herrn richte dein Begehren aus.","nl":"Dus wanneer je klaar ben met jouw bezigheden streef dan verder in aanbidding. En richt je streven (puur alleen) naar jouw Heer.","pt":"Então, quando estiverdes livre, esforça-te em orar, E dirige-te a teu Senhor em rogos.","sr":"A kad završiš, predaj se molitvi, i teži svome Gospodaru!"},
{"s":103,"v":"1-3","name":"العصر","ar":"وَٱلۡعَصۡرِ ۝١ إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ ۝٢ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ ۝٣","ru":"Клянусь предвечерним временем (или временем) Воистину, каждый человек в убытке кроме тех, которые уверовали, совершали праведные деяния, заповедали друг другу истину и заповедали друг другу терпение","en":"By time Indeed, mankind is in loss Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience","tr":"İkindi vaktine (Asra; çağa) and olsun ki İnsan hiç şüphesiz hüsran içindedir Ancak inanıp yararlı iş işleyenler, birbirlerine gerçeği tavsiye edenler ve sabırlı olmayı tavsiye edenler bunun dışındadır","fr":"Par le Temps L'homme est certes, en perdition sauf ceux qui croient et accomplissent les bonnes œuvres, s'enjoignent mutuellement la vérité et s'enjoignent mutuellement l'endurance","es":"Juro por el tiempo que los seres humanos están en la perdición excepto aquellos que crean, obren rectamente, y se aconsejen mutuamente con la verdad y con la paciencia [ante las adversidades]","de":"Beim Zeitalter! Der Mensch befindet sich wahrlich in Verlust, außer denjenigen, die glauben und rechtschaffene Werke tun und einander die Wahrheit eindringlich empfehlen und einander die Standhaftigkeit eindringlich empfehlen.","nl":"(Allah zweert) bij de tijd. Waarlijk, de (ongelovige) mens is verliezend (en in een staat van zelfvernietiging)! Behalve degenen die (in Allah en Zijn boodschapper) geloven (dus kennis opdoen) en goede daden verrichten (ernaar handelen), en elkaar aansporen tot de waarheid (en gehoorzaamheid aan Allah), en elkaar aansporen tot geduld.","pt":"Pelo tempo! Por certo, o ser humano está em perdição, Exceto aos que crêem e fazem as boas obras e se recomendam mutuamente a verdade, e se recomendam mutuamente a paciência.","sr":"Tako mi vremena, zaista je čovek na gubitku, samo nisu oni koji veruju i rade dobra dela, i koji jedni drugima preporučuju istinu i koji jedni drugima preporučuju strpljenje."},
{"s":112,"v":"1-4","name":"الإخلاص","ar":"قُلۡ هُوَ ٱللَّهُ أَحَدٌ ۝١ ٱللَّهُ ٱلصَّمَدُ ۝٢ لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ ۝٣ وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ ۝٤","ru":"Скажи: «Он - Аллах Единый Аллах Самодостаточный Он не родил и не был рожден и нет никого равного Ему»","en":"Say, \"He is Allah, [who is] One Allah, the Eternal Refuge He neither begets nor is born Nor is there to Him any equivalent","tr":"De ki: O Allah bir tektir Allah her şeyden müstağni ve her şey O'na muhtaçtır O doğurmamış ve doğmamıştır Hiçbir şey O'na denk değildir","fr":"Dis: «Il est Allah, Unique Allah, Le Seul à être imploré pour ce que nous désirons Il n'a jamais engendré, n'a pas été engendré non plus Et nul n'est égal à Lui»","es":"Di: \"Él es Al-lah, Uno Al-lah es el Absoluto No engendró ni fue engendrado Y no hay nada ni nadie que sea semejante a Él","de":"Sag: Er ist Allah, Einer, Allah, der Überlegene. Er hat nicht gezeugt und ist nicht gezeugt worden, und niemand ist Ihm jemals gleich.","nl":"Zeg: “Hij is Allah, de Enige (zo zou Allah de Enige moeten zijn in onze harten).\" Allah de Eeuwige, de Onafhankelijke (waarvan alles en iedereen afhankelijk is). Hij heeft niet verwerkt, noch is Hij verwekt. En er is niets of niemand die met Hem te vergelijken is, (in welk opzicht dan ook).”","pt":"Dize: \"Ele é Allah, Único.\" \"Allah é O Solicitado.\" \"Não gerou e não foi gerado.\" \"E não há ninguém igual a Ele.\"","sr":"Reci: „On je Allah - Jedan! Allah je Utočište svakom. Nije rodio i rođen nije, i niko Mu ravan nije!“"}];
